globalThis.process===void 0&&(globalThis.process={env:{},nextTick:function(e){setTimeout(e,0)},emit:function(){return!1}});import"react";import"react-dom";import"react/jsx-runtime";import"react-dom/client";var e={sender:`Gaia`,preview:`สวัสดี 👋 ขอบคุณที่ติดต่อเข้ามา เดี๋ยวฉันจะรีบตอบกลับนะ…`,ageLabel:`4 ชม.`},t=JSON.parse('{"demo-news-1":{"title":"Pioneer 2026: จดวันไว้ได้เลย","excerpt":"เรากลับมาที่ซานฟรานซิสโกอีกครั้งในวันที่ 8 ตุลาคม เปิดประตู 9 โมง คีย์โน้ต 10 โมง","body":"## สิ่งที่รอคุณอยู่\\n\\nคีย์โน้ตปีนี้พูดถึงสิ่งที่เราปล่อยออกมาอย่างเปิดเผยและสิ่งที่กำลังจะมาถึง เป็นการสาธิตสด ไม่ใช่สไลด์\\n\\n- **โรดแมปของ Gaia** - AI ของเราจะก้าวไปทางไหนใน 2 ไตรมาสข้างหน้า\\n- **เรื่องราวจากลูกค้า** - 3 ทีมเล่าว่าลดเวลาตอบกลับครั้งแรกลงครึ่งหนึ่งได้อย่างไร\\n- **เวิร์กช็อปลงมือทำ** - นำแล็ปท็อปมาสร้างโฟลว์ไปพร้อมกับวิศวกรของเรา\\n\\n## การเดินทาง\\n\\nสถานที่จัดงานคือ Pier 27 Cruise Terminal ริมถนน Embarcadero สถานี BART ที่ใกล้ที่สุดคือ Embarcadero เดินเลียบริมน้ำประมาณ 12 นาที\\n\\n## บัตร\\n\\nที่นั่งราคา early-bird มีจำนวนจำกัดและจะเปิดขายสัปดาห์หน้า ลูกค้าปัจจุบันได้สิทธิ์ก่อน อย่าลืมเช็กกล่องข้อความของคุณ\\n\\n> มาร่วมงานไม่ได้? คีย์โน้ตถ่ายทอดสด และบันทึกภาพจะมาลงที่นี่ภายในเย็นวันเดียวกัน"},"demo-news-2":{"title":"สิ่งที่เราปล่อยในเดือนเมษายน","excerpt":"ทริกเกอร์ระบบอัตโนมัติใหม่ 3 รายการ และการค้นหาในกล่องข้อความที่เร็วขึ้นมาก","body":"<p>เดือนเมษายนเป็นเดือนที่คึกคัก นี่คือทุกอย่างที่เราปล่อยออกมา สรุปให้ดูในแวบเดียว</p>\\n<table>\\n<thead><tr><th>ส่วนงาน</th><th>สิ่งที่เปลี่ยน</th><th>ทำไมจึงสำคัญ</th></tr></thead>\\n<tbody>\\n<tr><td>ค้นหาในกล่องข้อความ</td><td>ผลลัพธ์ทันทีขณะพิมพ์</td><td>50,000 การสนทนา ใช้เวลาไม่ถึง 100 มิลลิวินาที</td></tr>\\n<tr><td>ระบบอัตโนมัติ</td><td>ทริกเกอร์ใหม่ 3 รายการ</td><td>ทิ้งตะกร้า กลับมาเข้าหน้าเดิม ผู้เยี่ยมชมเงียบ</td></tr>\\n<tr><td>ช่องเขียนตอบ</td><td>ฉบับร่างยังอยู่แม้สลับแท็บ</td><td>ไม่มีข้อความที่พิมพ์ค้างหายอีกต่อไป</td></tr>\\n<tr><td>โหมดมืด</td><td>ไม่มีแสงขาววาบตอนโหลดครั้งแรก</td><td>โหลดหน้าเว็บมืดได้เนียนกว่าเดิม</td></tr>\\n</tbody>\\n</table>\\n<p>มาดูการค้นหาแบบใหม่ในการใช้งานจริง - ผลลัพธ์ขึ้นมาก่อนที่คุณจะพิมพ์เสร็จ</p>\\n<img src=\\"https://picsum.photos/seed/wexio-search/1024/576\\" alt=\\"การค้นหาในกล่องข้อความที่แสดงผลลัพธ์ทันที\\" />\\n<p>แตะที่รูปเพื่อดูใกล้ ๆ มีคำขอไหม? ตอบกลับที่นี่ได้เลย - เราอ่านทุกข้อความ</p>"},"demo-news-3":{"title":"Gaia พูดได้ 28 ภาษาแล้ว","excerpt":"ตรวจจับภาษาของผู้เยี่ยมชมอัตโนมัติหรือล็อกไว้ที่ภาษาเดียว ไม่ต้องตั้งค่าเพิ่ม","body":"<p>ตอนนี้ Gaia ตอบกลับได้ใน 28 ภาษา โดยตรวจจับอัตโนมัติจากข้อความแรกของผู้เยี่ยมชม คำถามที่เราพบบ่อยที่สุด</p>\\n<details><summary>การตรวจจับภาษาทำงานอย่างไร</summary><p>Gaia อ่านข้อความแรกแล้วตอบกลับด้วยภาษาเดียวกัน หากบทความช่วยเหลือของคุณมีภาษานั้น Gaia จะอ้างอิงบทความนั้น หากไม่มีจะตอบจากบทความที่ใกล้เคียงที่สุดและแจ้งให้คุณทราบถึงช่องว่างนั้น</p></details>\\n<details><summary>บังคับใช้ภาษาเดียวได้ไหม</summary><p>ได้ ล็อกภาษาไว้ที่ <strong>ตั้งค่า → AI → ภาษา</strong> แล้ว Gaia จะใช้ภาษานั้นเสมอไม่ว่าผู้เยี่ยมชมจะพิมพ์ภาษาอะไร</p></details>\\n<details><summary>ผู้ดูแลเห็นอะไรบ้าง</summary><p>บทสนทนาจะแสดงเป็นภาษาของทีมคุณ โดยเก็บข้อความต้นฉบับไว้คู่กับคำแปล</p></details>\\n<p>ชมตัวอย่างสั้น ๆ ตอน Gaia สลับภาษากลางบทสนทนา</p>\\n<img src=\\"https://picsum.photos/seed/wexio-lang/1024/576\\" alt=\\"Gaia ตอบกลับหลายภาษา\\" />"},"demo-news-4":{"title":"ส่งการสนทนาเข้า Slack ได้โดยตรง","excerpt":"เชื่อมต่อเว็บฮุกขาเข้าใดก็ได้กับช่อง Slack ไม่ต้องเขียนโค้ดเชื่อมต่อ","body":"## เชื่อมต่อได้ในสองคลิก\\n\\nไปที่ **การเชื่อมต่อ → Slack** กด *เชื่อมต่อ* แล้วอนุมัติสิทธิ์ เลือกช่องที่ต้องการให้การสนทนาใหม่ไปลง - ส่วนใหญ่ทีมต่าง ๆ ใช้ `#support`\\n\\n## สิ่งที่คุณจะได้รับ\\n\\n- ข้อความใน Slack ทันทีที่แชตเริ่มต้น พร้อมลิงก์กลับไปยังกล่องข้อความ\\n- คำตอบของผู้ดูแลจัดเป็นเธรดใต้ข้อความต้นฉบับ\\n- ตอบจาก Slack ได้เลย แล้วเราจะส่งถึงผู้เยี่ยมชมแบบเรียลไทม์\\n\\n## รองรับเว็บฮุกด้วย\\n\\nส่งอีเวนต์จากระบบของคุณเองอยู่แล้วใช่ไหม? ชี้เว็บฮุกใดก็ได้ไปที่ช่อง Slack ของคุณ แล้วข้ามการพัฒนาการเชื่อมต่อเองไปได้เลย"},"demo-news-5":{"title":"Inbox 2.0: คัดแยกได้โดยไม่ต้องใช้เมาส์","excerpt":"ชอร์ตคัตใหม่สำหรับมอบหมาย เลื่อน และแก้ไขให้เสร็จ - ทำได้จากคีย์บอร์ดทั้งหมด","body":"<p>Inbox 2.0 ให้ความสำคัญกับคีย์บอร์ดเป็นหลัก นี่คือสรุปชอร์ตคัต จัดกลุ่มตามสิ่งที่คุณกำลังทำ</p>\\n<div data-type=\\"tabs\\">\\n<div data-type=\\"tab\\"><div data-tab-label>เลื่อนดู</div><ul><li><code>j</code> / <code>k</code> - การสนทนาถัดไป / ก่อนหน้า</li><li><code>g</code> แล้วตามด้วย <code>i</code> - ไปที่กล่องข้อความ</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>จัดการ</div><ul><li><code>e</code> - แก้ไขเสร็จสิ้น</li><li><code>a</code> - มอบหมายให้ฉัน</li><li><code>s</code> - เลื่อนไว้ก่อน</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>เขียนตอบ</div><ul><li><code>Cmd+Enter</code> - ส่ง</li><li><code>/</code> - คำตอบที่บันทึกไว้</li><li><code>Cmd+K</code> - แผงคำสั่ง</li></ul></div>\\n</div>\\n<p>กล่องข้อความที่ออกแบบใหม่ - ทุกอย่างอยู่ในระยะแป้นพิมพ์</p>\\n<img src=\\"https://picsum.photos/seed/wexio-inbox/1024/576\\" alt=\\"กล่องข้อความที่ออกแบบใหม่โดยเน้นคีย์บอร์ด\\" />"},"demo-news-6":{"title":"ส่งออกและลบข้อมูลได้ด้วยตัวเอง","excerpt":"จัดการคำขอข้อมูลของผู้เยี่ยมชมได้ในคลิกเดียว พร้อมรองรับ GDPR ตั้งแต่ต้น","body":"## ส่งออก\\n\\nจากโปรไฟล์ของผู้เยี่ยมชมคนใดก็ได้ กด **ส่งออกข้อมูล** เพื่อสร้างไฟล์ JSON ที่รวมทุกข้อความ อีเวนต์ และแอตทริบิวต์ที่เราเก็บไว้ ดาวน์โหลดได้ทันที และบันทึกคำขอไว้เป็นหลักฐานให้คุณ\\n\\n## ลบ\\n\\n**ลบข้อมูล** จะลบผู้เยี่ยมชมและลบข้อความของเขาออกจากกล่องข้อความ การค้นหา และ CRM ที่เชื่อมต่อทุกระบบผ่านบริดจ์เว็บฮุกเดียวกัน การดำเนินการนี้ถูกบันทึกไว้และย้อนกลับไม่ได้\\n\\n## สำหรับเจ้าหน้าที่คุ้มครองข้อมูล (DPO) ของคุณ\\n\\n- ทุกการส่งออกและการลบมีการประทับเวลาและระบุผู้ดำเนินการ\\n- ตั้งระยะเวลาการเก็บรักษาได้ตามแต่ละเวิร์กสเปซ\\n- มีข้อตกลงการประมวลผลข้อมูลให้ตามคำขอ"},"demo-news-7":{"title":"Mobile SDK เวอร์ชันเบต้า: iOS และ Android","excerpt":"นำการสนทนาเดียวกันเข้าไปในแอปเนทีฟของคุณ เปิดรับสมัครเบต้าแล้ววันนี้","body":"## หนึ่งการสนทนา ทุกหน้าจอ\\n\\nผู้เยี่ยมชมที่เริ่มแชตบนเว็บไซต์ของคุณสามารถคุยต่อในแอปได้ โดยลงชื่อเข้าใช้แล้วและมีประวัติครบถ้วน Gaia ตัวเดิม ผู้ดูแลชุดเดิม กล่องข้อความเดียวกัน\\n\\n## สิ่งที่มีในเบต้า\\n\\n- ตัวเปิดแชตแบบเนทีฟสำหรับ SwiftUI และ Jetpack Compose\\n- การแจ้งเตือนแบบพุชเมื่อมีคำตอบใหม่\\n- คิวออฟไลน์ ข้อความจะถูกส่งเมื่อกลับมาเชื่อมต่ออีกครั้ง\\n\\n## เข้าร่วม\\n\\nเรารับทีมเข้าร่วมสัปดาห์ละไม่กี่ทีม ตอบกลับที่นี่พร้อมแพลตฟอร์มและจำนวนผู้ใช้งานต่อเดือนโดยประมาณ แล้วเราจะส่งคีย์ให้\\n\\n> เบต้าหมายถึงยังมีส่วนที่ไม่เรียบร้อย เราปล่อยการแก้ไขทุกสัปดาห์และอ่านรายงานบั๊กทุกฉบับ"},"demo-news-8":{"title":"ดูว่าคำตอบ AI ไหนได้ผลจริง","excerpt":"ติดตามว่าคำตอบของ Gaia แต่ละข้อนำไปสู่การแก้ปัญหา การส่งต่อ หรือการหลุดออกไป","body":"## มุมมองใหม่\\n\\n**การวิเคราะห์ → ผลลัพธ์ของ AI** แยกคำตอบของ Gaia แต่ละข้อตามสิ่งที่เกิดขึ้นต่อมา\\n\\n- **แก้ปัญหาแล้ว** - ผู้เยี่ยมชมได้สิ่งที่ต้องการและจากไปอย่างพอใจ\\n- **ส่งต่อแล้ว** - Gaia ส่งการสนทนาต่อให้เจ้าหน้าที่\\n- **หลุดออก** - ผู้เยี่ยมชมปิดวิดเจ็ตโดยที่ปัญหายังไม่ได้รับการแก้\\n\\n## ข้อมูลเชิงลึกรายบทความ\\n\\nเจาะดูบทความช่วยเหลือใดก็ได้เพื่อดูว่า Gaia อ้างอิงบทความนั้นบ่อยแค่ไหนและการอ้างอิงเหล่านั้นแก้ปัญหาได้หรือไม่ หากบทความที่มีทราฟฟิกสูงแก้ปัญหาได้น้อย มักแปลว่าต้องเขียนเนื้อหาใหม่ ไม่ใช่ปรับ AI\\n\\n## ลงมือแก้ไข\\n\\nเรียงตามอัตราการหลุดออกเพื่อหาคำถามที่ Gaia ตอบได้ยากที่สุด แล้วเพิ่มโฟลว์หรือบทความที่ตรงจุดกว่าเดิมเพื่อปิดช่องว่างนั้น"},"tags":{"events":"อีเวนต์","product":"ผลิตภัณฑ์","release":"รุ่นใหม่","ai":"AI","languages":"ภาษา","integrations":"การเชื่อมต่อ","slack":"Slack","inbox":"กล่องข้อความ","privacy":"ความเป็นส่วนตัว","security":"ความปลอดภัย","mobile":"มือถือ","beta":"เบต้า","analytics":"การวิเคราะห์"},"categories":{"company":"บริษัท","product":"ผลิตภัณฑ์","engineering":"วิศวกรรม"}}'),n=JSON.parse('{"categories":{"demo-cat-getting-started":{"title":"เริ่มต้นใช้งาน","description":"ติดตั้งวิดเจ็ตและตั้งค่าการสนทนาแรกของคุณ"},"demo-cat-automation":{"title":"ระบบอัตโนมัติ","description":"โฟลว์ ทริกเกอร์ และการตอบกลับอัตโนมัติด้วย AI"},"demo-cat-integrations":{"title":"การเชื่อมต่อ","description":"เชื่อมต่อ CRM, Slack และ CMS ของคุณ"},"demo-cat-billing":{"title":"การเรียกเก็บเงินและแพ็กเกจ","description":"ระดับราคา ใบแจ้งหนี้ และการจัดการที่นั่ง"}},"articles":{"demo-article-install":{"title":"ติดตั้งวิดเจ็ต Wexio บนเว็บไซต์ของคุณ","excerpt":"โค้ดสั้น ๆ ที่ใช้เวลา 30 วินาที วางก่อนแท็กปิด </body>","body":"## เพิ่มสคริปต์โหลดเดอร์\\n\\nวางโค้ดนี้ในทุกหน้าที่คุณต้องการให้วิดเจ็ตปรากฏ:\\n\\n```html\\n<script\\n  src=\\"https://cdn.wexio.io/widget/loader.js\\"\\n  data-public-key=\\"pk_live_YOUR_KEY\\"\\n><\/script>\\n```\\n\\nโหลดเดอร์จะเพิ่มปุ่มลอยที่มุมขวาล่าง คลิกเพื่อเปิดแผงแชต\\n\\n## ตรวจสอบการติดตั้ง\\n\\n- เปิดหน้าที่มีโค้ดนี้\\n- เปิดคอนโซลของเบราว์เซอร์\\n- คุณควรเห็น `[wexio] widget mounted`\\n\\n## ปรับแต่งรูปลักษณ์\\n\\nวิดเจ็ตจะอ่านสีของแบรนด์จากแดชบอร์ดของคุณ อัปเดตได้ที่ **ตั้งค่า → แบรนด์**\\n\\n> ต้องการความช่วยเหลือ? แตะ \\"ยังต้องการความช่วยเหลือ? ส่งข้อความหาเรา\\" ด้านล่าง แล้วเราจะแนะนำทีละขั้นตอน"},"demo-article-flows":{"title":"สร้างโฟลว์อัตโนมัติแรกของคุณ","excerpt":"ลากแล้ววาง สร้างบอทต้อนรับได้ในไม่ถึงห้านาที","body":"## โฟลว์คืออะไร\\n\\nโฟลว์คือแผนผังเล็ก ๆ ของขั้นตอนการสนทนา - คำถาม คำตอบ และเงื่อนไข - ที่ทำงานทุกครั้งที่ผู้เยี่ยมชมตรงกับทริกเกอร์\\n\\n## ทริกเกอร์ 3 ประเภท\\n\\n1. **ผู้เยี่ยมชมเปิดวิดเจ็ต** - ทักทายผู้ที่มาครั้งแรก\\n2. **ผู้เยี่ยมชมถามคำถาม** - Gaia (AI) พยายามตอบ หากตอบไม่ได้ โฟลว์จะเข้ามารับช่วงต่อ\\n3. **ได้รับเว็บฮุก** - CMS หรือแพลตฟอร์มอีคอมเมิร์ซของคุณส่งอีเวนต์มา โฟลว์จะเริ่มในแชตที่ถูกต้อง\\n\\n## แนวปฏิบัติที่ดี\\n\\n- ให้คำตอบแรกสั้นกว่า 80 ตัวอักษร\\n- เสนอปุ่มตอบด่วน 2-3 ปุ่ม แทนการถามแบบให้พิมพ์เอง\\n- เตรียมทางออกไว้เสมอ - *\\"คุยกับเจ้าหน้าที่\\"*"},"demo-article-slack":{"title":"ส่งต่อแชตไปยัง Slack","excerpt":"สะท้อนทุกการสนทนาใหม่ไปยังช่อง Slack ที่คุณเลือก","body":"## เชื่อมต่อเวิร์กสเปซของคุณ\\n\\nที่ **การเชื่อมต่อ → Slack** คลิก *เชื่อมต่อ* คุณจะถูกพาไปยังหน้า OAuth ของ Slack - อนุมัติสิทธิ์ที่ร้องขอ (`chat:write`, `channels:read`)\\n\\n## เลือกช่อง\\n\\nหลังจากอนุญาตแล้ว เลือกช่องปลายทาง (หรือสร้างช่องใหม่ เช่น `#support`)\\n\\n## สิ่งที่ถูกส่งต่อ\\n\\n- ข้อความแรก พร้อมดีปลิงก์กลับไปยังกล่องข้อความ wexio\\n- คำตอบของผู้ดูแลในรูปแบบข้อความเธรด\\n- คำตอบของผู้เยี่ยมชมแบบเรียลไทม์ผ่านบริดจ์ SSE\\n\\n## ทิศทางย้อนกลับ\\n\\nผู้ดูแลตอบ *จาก* Slack ได้ - wexio จะรับฟังคำตอบในเธรดของ Slack แล้วส่งกลับไปยังวิดเจ็ต"},"demo-article-billing":{"title":"อัปเดตแพ็กเกจและข้อมูลการเรียกเก็บเงิน","excerpt":"เปลี่ยนระดับ เปลี่ยนบัตร หรือดาวน์โหลดใบแจ้งหนี้","body":"## แพ็กเกจ\\n\\n- **Free** - 1 วิดเจ็ต ฟีเจอร์พื้นฐาน ป้าย \\"Powered by Wexio\\"\\n- **Standard** - วิดเจ็ตไม่จำกัด ระบบอัตโนมัติ การเชื่อมต่อ\\n- **Enterprise** - ไวต์เลเบล SLA ฝ่ายสนับสนุนเฉพาะ\\n\\n## เปลี่ยนแพ็กเกจ\\n\\n**ตั้งค่า → การเรียกเก็บเงิน → เปลี่ยนแพ็กเกจ** การอัปเกรดมีผลทันที การดาวน์เกรดจะมีผลเมื่อสิ้นสุดรอบปัจจุบัน\\n\\n## ใบแจ้งหนี้\\n\\nดาวน์โหลดใบแจ้งหนี้ทุกใบเป็น PDF ได้จาก **การเรียกเก็บเงิน → ประวัติ** เรายังส่งสำเนาทางอีเมลทุกครั้งที่ต่ออายุด้วย"},"demo-article-theme":{"title":"ปรับแต่งธีมของวิดเจ็ต","excerpt":"ทำให้วิดเจ็ตเข้ากับแบรนด์ของคุณ - สี ความโค้งมน โหมดมืด","body":"## สีของแบรนด์\\n\\nที่ **ตั้งค่า → แบรนด์** กำหนดค่าดังนี้:\\n\\n- **สีหลัก** - ใช้กับปุ่มเปิดแชต ปุ่มส่ง และเส้นโฟกัส\\n- **พื้นหลัง** - พื้นผิวของแผง (โหมดสว่าง) และคู่สีสำหรับโหมดมืด\\n\\n## ความโค้งมน\\n\\nเลือกจาก `sm`, `md`, `lg` เพื่อให้ดูคมขึ้นหรือนุ่มนวลขึ้น การเปลี่ยนแปลงมีผลทันทีกับทุกวิดเจ็ตในทุกหน้า\\n\\n## โหมดมืด\\n\\nค่าเริ่มต้น = ตามการตั้งค่าระบบของผู้เยี่ยมชม ล็อกไว้ที่ **สว่างเสมอ** หรือ **มืดเสมอ** หากเว็บไซต์ของคุณเองไม่รองรับโหมดมืด"},"demo-article-handoff":{"title":"ส่งต่อจาก Gaia ให้ผู้ดูแลที่เป็นคน","excerpt":"เมื่อ AI ไม่เพียงพอ - ส่งผู้เยี่ยมชมไปหาเพื่อนร่วมทีม","body":"## ทริกเกอร์\\n\\nGaia จะส่งต่ออัตโนมัติเมื่อ:\\n\\n- ผู้เยี่ยมชมพิมพ์ *\\"ขอคุยกับเจ้าหน้าที่\\"* (หรือคำที่เทียบเท่าในภาษาอื่น)\\n- ถามคำถามเดิมสองครั้งโดยยังไม่ได้รับการแก้ไข\\n- เจตนาของผู้เยี่ยมชมตรงกับกฎการกำหนดเส้นทาง (เช่น การเรียกเก็บเงิน → ทีมการเงิน)\\n\\n## การกำหนดเส้นทาง\\n\\nตั้งค่า **การกำหนดเส้นทาง → กฎ** เพื่อส่งเจตนาบางอย่างไปยังทีมหรือผู้ดูแลเฉพาะ รองรับทั้งแบบ round-robin และแบบภาระงานน้อยที่สุด\\n\\n## นอกเวลาทำการ\\n\\nหากไม่มีผู้ดูแลออนไลน์ Gaia จะเสนอแบบฟอร์มขอให้โทรกลับหรือส่งต่อทางอีเมล แทนที่จะแสร้งว่ามีคนว่างอยู่"},"demo-article-crm":{"title":"ซิงก์การสนทนาไปยัง CRM ของคุณ","excerpt":"ส่งทุกแชตเข้า HubSpot, Salesforce หรือ Pipedrive","body":"## CRM ที่รองรับ\\n\\n- HubSpot (OAuth)\\n- Salesforce (OAuth)\\n- Pipedrive (โทเค็น API)\\n- กำหนดเองผ่านเว็บฮุก\\n\\n## สิ่งที่ซิงก์\\n\\n- การสนทนาใหม่จะสร้างผู้ติดต่อ (หากยังไม่มี) และโน้ต\\n- คำตอบของผู้ดูแลจะถูกต่อท้ายในไทม์ไลน์ของผู้ติดต่อ\\n- แท็กที่ใส่ใน wexio จะสะท้อนไปยัง CRM\\n\\n## สองทาง\\n\\nโน้ตของผู้ดูแลที่เพิ่มใน CRM สามารถส่งกลับมายัง wexio ผ่านตัวรับเว็บฮุก - ดู *การเชื่อมต่อ → เว็บฮุก → ขาเข้า*"},"demo-article-shortcuts":{"title":"ชอร์ตคัตคีย์บอร์ดสำหรับผู้ดูแล","excerpt":"คัดแยกเร็วขึ้นสองเท่า - ไม่ต้องใช้เมาส์","body":"## การเลื่อนดูกล่องข้อความ\\n\\n- `j` / `k` - การสนทนาถัดไป / ก่อนหน้า\\n- `e` - แก้ไขเสร็จสิ้น\\n- `a` - มอบหมายให้ฉัน\\n- `s` - เลื่อนไว้ก่อน\\n\\n## ช่องเขียนตอบ\\n\\n- `Cmd+Enter` - ส่ง\\n- `/` - เปิดตัวเลือกคำตอบที่บันทึกไว้\\n- `Cmd+K` - แผงคำสั่ง (ทุกอย่าง)\\n\\n## เคล็ดลับ\\n\\nวางเมาส์บนปุ่มใดก็ได้ในแดชบอร์ด - ทูลทิปจะแสดงชอร์ตคัตของปุ่มนั้น"}},"tags":{"setup":"การตั้งค่า","install":"การติดตั้ง","automation":"ระบบอัตโนมัติ","flows":"โฟลว์","integrations":"การเชื่อมต่อ","slack":"Slack","billing":"การเรียกเก็บเงิน","plans":"แพ็กเกจ","design":"การออกแบบ","ai":"AI","crm":"CRM","productivity":"ประสิทธิภาพการทำงาน","inbox":"กล่องข้อความ"}}'),r={visitorName:`คุณ`,messages:{"m-demo-1":{text:`สวัสดี 👋 ฉันคือ Gaia AI ของ Wexio มีอะไรให้ช่วยไหม`,ageLabel:`09:41`,buttons:[`ราคาเป็นอย่างไร`,`ทำอะไรได้บ้าง`,`คุยกับเจ้าหน้าที่`]},"m-demo-2":{text:`ขอดูหน่อยได้ไหมว่าวิดเจ็ตหน้าตาเป็นอย่างไร`,ageLabel:`09:41`},"m-demo-3":{text:``,ageLabel:`09:42`,mediaAlts:[`ภาพหน้าจอผลิตภัณฑ์`]},"m-demo-4":{text:``,ageLabel:`09:42`,mediaAlts:[`ลูกโลกหมุน`]},"m-demo-5":{text:`เยี่ยมเลย! 😄 นี่คือภาพบางส่วนจากทีมของเรา`,ageLabel:`09:43`},"m-demo-6":{text:`ไฮไลต์บางส่วนของแดชบอร์ด`,ageLabel:`09:43`,mediaAlts:[`ภาพรวมแดชบอร์ด`,`การวิเคราะห์`,`กล่องข้อความ`,`รายงาน`]},"m-demo-7":{text:``,ageLabel:`09:44`,mediaAlts:[`แนะนำการใช้งานแบบรวดเร็ว`]},"m-demo-8":{text:``,ageLabel:`09:44`,mediaAlts:[`ข้อความเสียง`]},"m-demo-9":{text:``,ageLabel:`09:45`,mediaAlts:[`คู่มือเริ่มต้นใช้งาน`]},"m-demo-9b":{text:``,ageLabel:`09:45`,mediaAlts:[`การเชื่อมต่อ Wexio`]},"m-demo-10":{text:`พร้อมลองใช้ด้วยตัวเองหรือยัง`,ageLabel:`09:45`,buttons:[`เปิดแซนด์บ็อกซ์`,`นัดคุยทางโทรศัพท์`,`คุยต่อ`]}}},i={messengerDescription:`ทีมงานของเราพร้อมช่วยเหลือเช่นกัน`,messengerMessage:`สวัสดี 👋 ถามอะไรก็ได้ หรือเลือกการดำเนินการด่วน`},a={welcome:{system:`ตอนนี้คุณกำลังคุยกับ Gaia ผู้ช่วย AI ของเรา`,hint:`เคล็ดลับ: แนบไฟล์หรืออัดข้อความเสียงได้ทุกเมื่อ`,greeting:`สวัสดี 👋 ฉันคือ Gaia AI ของ Wexio ถามอะไรก็ได้ หรือเลือกการทำงานด่วนเพื่อเริ่มต้น`},replies:{pricing:{text:`Wexio ใช้ฟรีสำหรับ 1 วิดเจ็ต ส่วนแพ็กเกจแบบชำระเงินเริ่มที่ $39/เดือน และปลดล็อกระบบอัตโนมัติ การเชื่อมต่อ และไวต์เลเบล`,planBtn:`ดูระดับแพ็กเกจ`,salesBtn:`คุยกับฝ่ายขาย`},gaia:{text:`Gaia คือเอเจนต์ AI ที่ตอบคำถามของผู้เยี่ยมชมได้ทันที เรียนรู้จากบทความช่วยเหลือของคุณ และส่งต่อให้เจ้าหน้าที่เมื่อช่วยไม่ได้`,handoffBtn:`การส่งต่อทำงานอย่างไร`},human:{text:`ได้เลย - ฉันจะดึง Alex จากทีมเข้ามาช่วย ในเวลาทำการจะตอบกลับภายในไม่กี่นาที`},fallback:{text:`รับทราบ - ขอตรวจสอบสักครู่แล้วจะกลับมาตอบ`},voice:{text:`ได้รับข้อความเสียงของคุณแล้ว - ขอตรวจสอบแล้วจะกลับมาตอบ`}}},o={main:`พร้อมลองใช้ด้วยตัวเองหรือยัง`,billing:`ขอบคุณค่ะ! ฉันส่งคำถามเรื่องใบแจ้งหนี้ของคุณต่อให้ทีมการเรียกเก็บเงินแล้ว`,integrations:`จะเชื่อมต่อ WhatsApp กับบัญชีของฉันได้อย่างไร`},s={recentMessage:e,news:t,help:n,conversation:r,playgroundDefaults:i,messenger:a,threads:o};export{r as conversation,s as default,n as help,a as messenger,t as news,i as playgroundDefaults,e as recentMessage,o as threads};
